/** The widest a chip's label may render before it has to give ground. */
export const CHIP_LABEL_MAX = 28;

/**
 * Shorten a label to fit a chip, cutting at a word boundary when there is one to cut at.
 *
 * One helper rather than a `text-overflow: ellipsis` rule per surface, because CSS truncation
 * is invisible to everything that is not the browser: the accessible name keeps the full
 * string, a test asserting on the visible text reads the untruncated one, and two surfaces
 * showing "the same" label disagree about where it ends. Doing it in one function means the
 * card, the tile and the rail cut identically, and the tooltip carries what was cut.
 */
export function chipLabel(text: string, max = CHIP_LABEL_MAX): string {
  const clean = text.replace(/\s+/g, " ").trim();
  if (clean.length <= max) return clean;
  // The last space in the final quarter, so a cut lands between words when one is close and
  // mid-word when it is not - a label cut at the first space would lose most of a long name.
  const cut = clean.lastIndexOf(" ", max);
  const at = cut > max * 0.75 ? cut : max;
  return `${clean.slice(0, at).trimEnd()}…`;
}

/** What the tooltip says when a label was shortened: the whole thing, or nothing at all. */
export function chipTitle(text: string, max = CHIP_LABEL_MAX): string | undefined {
  const clean = text.replace(/\s+/g, " ").trim();
  return clean.length > max ? clean : undefined;
}

import assert from "node:assert/strict";
import test from "node:test";
import { chipLabel, chipTitle } from "./chip-label.ts";

test("a short label is returned as it was written", () => {
  assert.equal(chipLabel("Approved"), "Approved");
  assert.equal(chipTitle("Approved"), undefined);
});

test("a long label cuts at the last word boundary near the limit", () => {
  assert.equal(chipLabel("Move the ledger to cursor pagination", 24), "Move the ledger to…");
});

test("a label with no late boundary cuts mid-word rather than losing the name", () => {
  assert.equal(chipLabel("Retirethelegacyingestroute", 12), "Retiretheleg…");
});

test("collapsed whitespace is measured, not the raw string", () => {
  assert.equal(chipLabel("Stop   the\n token refresh", 20), "Stop the token…");
});

test("the tooltip carries the whole label exactly when one was cut", () => {
  assert.equal(chipTitle("Move the ledger to cursor pagination", 24), "Move the ledger to cursor pagination");
});
